from collections import deque
def findMaxValueOfEquation(points, k):
    dq = deque()
    best = float('-inf')
    for x, y in points:
        while dq and x - dq[0][0] > k:
            dq.popleft()
        if dq:
            best = max(best, dq[0][1] + x + y)
        while dq and dq[-1][1] <= y - x:
            dq.pop()
        dq.append((x, y - x))
    return best

